/* musl src/unistd/write.c: the same source in both builds */
ssize_t write(int fd, const void *buf, size_t count)
{
    return syscall_cp(SYS_write, fd, buf, count);
}

/* Linux build: musl arch/x86_64/syscall_arch.h (write itself goes
 * through __syscall_cp to the 6-argument form; all end the same way) */
static __inline long __syscall3(long n, long a1, long a2, long a3)
{
    unsigned long ret;
    __asm__ __volatile__ ("syscall" : "=a"(ret) : "a"(n), "D"(a1),
                          "S"(a2), "d"(a3) : "rcx", "r11", "memory");
    return ret;
}

/* Unikraft build: lib-musl patch to src/internal/syscall.h */
#define __syscall(...)    uk_syscall_r_static(__VA_ARGS__)
#define __syscall_cp(...) uk_syscall_r_static(__VA_ARGS__)
/* Build-time generated macros turn
 *   uk_syscall_r_static(SYS_write, fd, buf, count)
 * into
 *   uk_syscall_r_write(fd, buf, count)   (a plain call) */

// Application source, unchanged
n = write(1, "hi\n", 3);

// Linux guest: libc puts SYS_write in rax and
// executes the syscall instruction. The CPU switches
// to kernel mode, runs entry code (and swaps page
// tables if KPTI is on), then calls the write handler.

// Unikraft: the shim defines the handler as a C function
// (excerpt, lib/posix-fdio/fd-shim.c)
UK_SYSCALL_R_DEFINE(ssize_t, write, int, fd,
                    const void *, buf, size_t, count)
{
    ssize_t r;
    union uk_shim_file sf;
    switch (uk_fdtab_shim_get(fd, &sf)) {
    case UK_SHIM_OFILE:
        r = uk_sys_write(sf.ofile, buf, count);
        uk_ofile_release(sf.ofile);
        break;
    default:
        r = -EBADF;
    }
    return r;
}

/* Unikraft: every allocator implements struct uk_alloc.
 * Callers choose the backend explicitly. */
static inline void *uk_malloc(struct uk_alloc *a, __sz size)
{
    if (unlikely(!a)) {
        errno = ENOMEM;
        return __NULL;
    }
    return uk_do_malloc(a, size);  /* via a's function pointers */
}

/* plain malloc() in the application goes to the default
 * allocator chosen at configure time (buddy, TLSF,
 * tinyalloc, mimalloc, ...). */

let run t =
  let rec aux () =
    Lwt.wakeup_paused ();
    Time.restart_threads Time.time;
    match Lwt.poll t with
    | Some () -> ()
    | None ->
        let timeout =
          if Lwt.paused_count () > 0 then 0L
          else match Time.select_next () with
            | None -> Int64.add (Time.time ()) (Duration.of_day 1)
            | Some tm -> tm
        in
        let ready_set = solo5_yield timeout in
        if not (Int64.equal 0L ready_set) then
          wake_threads_waiting_on ready_set;
        aux ()
  in
  aux ()
